package com.lyra.studio; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; import android.app.Activity; import android.view.WindowManager; import android.webkit.WebView; import android.webkit.WebSettings; @DesignerComponent(version = 1, description = "Custom WebViewer com recursos avancados e adaptacao ao teclado.", category = ComponentCategory.EXTENSION, nonVisible = true, iconName = "images/extension.png") @SimpleObject(external = true) public class CustomWebViewer extends AndroidNonvisibleComponent { private Activity activity; public CustomWebViewer(ComponentContainer container) { super(container.$form()); this.activity = container.$context(); } /* Adapta a janela do aplicativo para redimensionar quando o teclado abrir, evitando que cubra o conteudo web */ @SimpleFunction(description = "Adapta a tela para que o teclado virtual nao cubra o conteudo do WebViewer.") public void AdaptarTeclado() { this.activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } /* Configura recursos avancados no WebViewer do MIT App Inventor */ @SimpleFunction(description = "Aplica configuracoes avancadas (DOM Storage, JS) a um WebViewer selecionado.") public void ConfigurarRecursosAvancados(WebViewer webViewer) { WebView webView = (WebView) webViewer.getView(); WebSettings settings = webView.getSettings(); /* Habilita armazenamento DOM para carregamento de sites modernos e dinamicos */ settings.setDomStorageEnabled(true); /* Garante o funcionamento de scripts JS */ settings.setJavaScriptEnabled(true); /* Permite zoom nativo porem ocultando os botoes de controle na tela */ settings.setBuiltInZoomControls(true); settings.setDisplayZoomControls(false); } }